// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.lang.management.ManagementFactory;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import com.sun.management.ThreadMXBean;

class LmdbWideDistinctPartitionResetTest {

	private static final int WIDTH = 8;
	private static final int ONE_KEY_IN_SECOND_BLOCK = 4097;
	private static final int KEY_BLOCK_BYTES = 256 * 1024;

	@Test
	void adjacentPartitionsReuseSecondKeyBlock() {
		var table = new WideDistinctTupleSet(WIDTH);
		var key = new long[WIDTH];
		for (int i = 0; i < 4; i++) {
			checkPartition(table, key, ONE_KEY_IN_SECOND_BLOCK, i * 100_000L);
		}

		long allocated = allocatedBytes(() -> {
			for (int i = 4; i < 16; i++) {
				checkPartition(table, key, ONE_KEY_IN_SECOND_BLOCK, i * 100_000L);
			}
		});
		// Reallocating twelve 256 KiB blocks costs at least 3 MiB. Allow ample room for VM/test overhead.
		assertTrue(allocated < 1_048_576L, "Repeated wide partitions allocated " + allocated + " bytes");
	}

	@Test
	void keysWiderThanTheBlockBudgetRequireANewSpillBlock() {
		int width = KEY_BLOCK_BYTES / Long.BYTES + 1;
		var table = new WideDistinctTupleSet(width);
		var key = new long[width];
		checkPartition(table, key, 2, 0);

		long allocated = allocatedBytes(() -> checkPartition(table, key, 2, 0));
		assertTrue(allocated >= (long) width * Long.BYTES,
				"Spilling keys wider than the block budget allocated " + allocated + " bytes");
	}

	@Test
	void emptyPartitionReleasesTheSpareKeyBlock() {
		var table = new WideDistinctTupleSet(WIDTH);
		var key = new long[WIDTH];
		checkPartition(table, key, ONE_KEY_IN_SECOND_BLOCK, 0);
		checkPartition(table, key, 0, 0);

		long allocated = allocatedBytes(() -> checkPartition(table, key, ONE_KEY_IN_SECOND_BLOCK, 0));
		assertTrue(allocated >= KEY_BLOCK_BYTES, "Spilling after an empty partition allocated " + allocated + " bytes");
	}

	@ParameterizedTest
	@ValueSource(ints = { 64, 1 << 30 })
	void resetForgetsExactKeysAcrossSizesAndIndexOverflow(int maxBuckets) {
		var table = new WideDistinctTupleSet(WIDTH, maxBuckets);
		var key = new long[WIDTH];
		int large = maxBuckets == 64 ? 150 : 2 * ONE_KEY_IN_SECOND_BLOCK;
		int[] sizes = { large, large, 1, 0, 2, large, 127, 0 };
		for (int size : sizes) {
			checkPartition(table, key, size, Long.MIN_VALUE);
		}
	}

	private static long allocatedBytes(Runnable readPartition) {
		var management = ManagementFactory.getThreadMXBean();
		assumeTrue(management instanceof ThreadMXBean);
		var allocations = (ThreadMXBean) management;
		assumeTrue(allocations.isThreadAllocatedMemorySupported());
		boolean wasEnabled = allocations.isThreadAllocatedMemoryEnabled();
		if (!wasEnabled) {
			allocations.setThreadAllocatedMemoryEnabled(true);
		}
		try {
			long thread = Thread.currentThread().threadId();
			long before = allocations.getThreadAllocatedBytes(thread);
			readPartition.run();
			return allocations.getThreadAllocatedBytes(thread) - before;
		} finally {
			if (!wasEnabled) {
				allocations.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static void checkPartition(WideDistinctTupleSet table, long[] key, int size, long first) {
		for (int i = 0; i < size; i++) {
			key[0] = first + i;
			key[1] = i % 3;
			key[key.length - 1] = key[0] * 0x9e3779b97f4a7c15L;
			assertTrue(table.add(key));
			assertFalse(table.add(key));
		}
		// Probe the first key again after crossing a key block or an index overflow segment.
		if (size != 0) {
			key[0] = first;
			key[1] = 0;
			key[key.length - 1] = first * 0x9e3779b97f4a7c15L;
			assertFalse(table.add(key));
		}
		assertEquals(size, table.size());
		table.clear();
		assertEquals(0, table.size());
	}
}
